syntax:
const type *ptr; // pointer to a constant data (data cannot be modified via ptr)
 type *const ptr; // constant pointer to data (pointer cannot be reassigned)
 const type *const ptr; // constant pointer to constant data

code_example:
const int *p; // p points to an int that should not be modified through p
int value = 42;
p = &value; // OK
// *p = 10; // Error: attempting to modify read-only data
int other_value = 100;
p = &other_value; // OK, pointer reassignment allowed
int *const q = &value; // q is a constant pointer to int
// q = &other_value; // Error: cannot reassign q
*q = 55; // OK: modifying the data pointed to by q
const int *const r = &value; // r is a constant pointer to constant int
// r = &other_value; // Error: cannot reassign r
// *r = 77; // Error: cannot modify data through r
